import {uid,scene,chapter,createProject,validate,snapshot,restore,applyReview} from './model.js';
import {LIBRARY_KEY,LEGACY_KEY,loadLibrary,activeBook,importIntoLibrary,validateLibrary,createLibrary} from './library.js';
import {LibraryView} from './library-view.js';
import {icon,actionIcon,decorateIcons} from './icons.js';
const $=s=>document.querySelector(s), esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let library,p,view='library',cid,sid,free=false,filter='',reviewId=null,tab='original',loadFailure=false,migrated=false;
try{({library,migrated}=loadLibrary(localStorage));}catch{library=createLibrary();loadFailure=true;}
p=activeBook(library).project;
const libraryView=new LibraryView(()=>library,{onOpen:openBook,onChange:()=>{p=activeBook(library).project;save();},onBackup:backupLibrary,onImport:()=>$('#file').click()});
function openBook(id){library.activeBookId=id;p=activeBook(library).project;cid=p.chapters.find(c=>!c.trashed)?.id;sid=current()?.scenes[0].id;filter='';reviewId=null;tab='original';view='write';document.body.classList.remove('focus');save();render();$('#chapterTitle')?.focus();}
function backupLibrary(){download('MORIARTY_BIBLIOTECA.moriarty.json',JSON.stringify(library,null,2));}
function downloadRecovery(){for(const key of [LIBRARY_KEY,LEGACY_KEY]){let raw;try{raw=localStorage.getItem(key);}catch{}if(raw!==null&&raw!==undefined)download(key+'.recuperacion.txt',raw,'text/plain');}}

cid=p.chapters.find(c=>!c.trashed)?.id;sid=current()?.scenes[0].id;
function current(){return p.chapters.find(c=>c.id===cid&&!c.trashed);}function selectedScene(){return current()?.scenes.find(s=>s.id===sid);}
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function save(){if(loadFailure){$('#saved').textContent='⚠ Guardado bloqueado · Recupera un respaldo';return false;}try{localStorage.setItem(LIBRARY_KEY,JSON.stringify(library));$('#saved').textContent='✓ Biblioteca guardada en este dispositivo';count();return true;}catch{$('#saved').textContent='⚠ No se pudo guardar · Respalda la biblioteca';count();return false;}}
function count(){if(view==='library'){$('#words').textContent=`${library.books.length} ${library.books.length===1?'libro':'libros'} · ${library.sagas.length} ${library.sagas.length===1?'saga':'sagas'}`;return;}const n=p.chapters.filter(c=>!c.trashed).flatMap(c=>c.scenes).map(s=>s.text).join(' ').trim();$('#words').textContent=`${n?n.split(/\s+/u).length:0} palabras · ${p.chapters.filter(c=>!c.trashed).length} capítulos`;}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function btn(id,text,cls=''){return `<button id="${id}" class="${cls}">${icon(actionIcon(id))}<span>${text.replace(/^[＋←]\s*/u,'')}</span></button>`;}function bind(id,fn){const el=$('#'+id);if(el)el.onclick=fn;}
function select(c,s){cid=c.id;sid=s?.id||c.scenes[0].id;render();}
function sidebar(){const el=$('#sidebar');el.innerHTML=`<div class="eyebrow">MANUSCRITO</div><input class="field" id="search" placeholder="Buscar texto o capítulo…" aria-label="Buscar"><div id="chapterList"></div>${btn('addChapter','＋ Nuevo capítulo')}<details><summary>Papelera</summary>${p.chapters.filter(c=>c.trashed).map(c=>`<button data-recover="${c.id}">↶ ${esc(c.title)}</button>`).join('')}</details>`;$('#search').value=filter;$('#search').oninput=e=>{filter=e.target.value;chapterList();};chapterList();bind('addChapter',()=>{const c=chapter();const n=p.chapters.length;c.x=40+(n%7)*200;c.y=40+Math.floor(n/7)*160;p.chapters.push(c);view='write';save();select(c);});el.querySelectorAll('[data-recover]').forEach(b=>b.onclick=()=>{p.chapters.find(c=>c.id===b.dataset.recover).trashed=false;save();render();});}
function chapterList(){$('#chapterList').innerHTML=p.chapters.filter(c=>!c.trashed&&(`${c.title} ${c.scenes.map(s=>s.text).join(' ')}`).toLowerCase().includes(filter.toLowerCase())).map((c,i)=>`<button class="${c.id===cid?'selected':''}" data-chapter="${c.id}">${i+1}. ${esc(c.title)}</button>${c.id===cid?c.scenes.map(s=>`<button class="scene ${s.id===sid?'selected':''}" data-scene="${s.id}">▱ ${esc(s.title)}</button>`).join(''):''}`).join('');$('#chapterList').querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{view='write';select(p.chapters.find(c=>c.id===b.dataset.chapter));});$('#chapterList').querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{sid=b.dataset.scene;view='write';render();});}
function render(){
 const home=view==='library';document.body.classList.toggle('library-mode',home);
 $('#projectTitle').value=p.title;$('#projectTitle').hidden=home;$('#libraryTitle').hidden=!home;
 $('#export').innerHTML=icon('download')+`<span>${home?'Respaldar biblioteca':'Exportar libro'}</span>`;
 $('#txt').hidden=home;
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 if(home)libraryView.render();else{sidebar();({write:writeView,board:boardView,archive:archiveView,timeline:timelineView,review:reviewView}[view])();}
 $('#recoveryBanner').hidden=!loadFailure;count();decorateIcons();
}
function writeView(){const c=current(),s=selectedScene();if(!c||!s){$('#main').innerHTML='<h1>Tu siguiente historia empieza aquí.</h1><p>Crea un capítulo en el manuscrito o recupera uno de la papelera.</p>';return;}$('#main').innerHTML=`<div class="toolbar"><span class="eyebrow">ESTUDIO DE ESCRITURA</span><span class="spacer"></span>${btn('focus','Modo enfoque')}${btn('versions','Versiones')}${btn('reviewStart','Revisar escena')}</div><article class="editor"><input id="chapterTitle" class="title" aria-label="Título del capítulo" value="${esc(c.title)}"><div class="toolbar"><select id="sceneSelect" class="field" aria-label="Escena">${c.scenes.map(s=>`<option value="${s.id}" ${s.id===sid?'selected':''}>${esc(s.title)}</option>`).join('')}</select>${btn('addScene','＋ Escena')}<span class="spacer"></span>${btn('trashChapter','A papelera')}</div><input id="sceneTitle" class="subtitle" aria-label="Título de escena" value="${esc(s.title)}"><textarea id="text" class="manuscript" aria-label="Texto de la escena" placeholder="Escribe aquí. Esta historia es tuya…" spellcheck="true">${esc(s.text)}</textarea><p class="muted">Texto plano · Guardado local · Exporta un respaldo para llevarlo a otro dispositivo.</p></article>`;$('#chapterTitle').oninput=e=>{c.title=e.target.value;save();chapterList();};$('#sceneTitle').oninput=e=>{s.title=e.target.value;$('#sceneSelect').selectedOptions[0].textContent=s.title;chapterList();save();};$('#text').oninput=e=>{s.text=e.target.value;save();};$('#sceneSelect').onchange=e=>{sid=e.target.value;render();};bind('addScene',()=>{const s=scene();c.scenes.push(s);save();select(c,s);});bind('focus',()=>{const active=document.body.classList.toggle('focus');$('#focus').innerHTML=icon('focus')+'<span>'+(active?'Salir de enfoque':'Modo enfoque')+'</span>';});bind('trashChapter',()=>{c.trashed=true;cid=p.chapters.find(c=>!c.trashed)?.id;sid=current()?.scenes[0].id;save();render();});bind('versions',versionsView);bind('reviewStart',()=>{snapshot(c,'Antes de revisión');const r={id:uid(),chapterId:c.id,sceneId:s.id,base:s.text,proposal:s.text,instruction:''};p.reviews.push(r);reviewId=r.id;view='review';save();render();});}
function versionsView(){const c=current();$('#main').innerHTML=`<div class="toolbar">${btn('back','← Manuscrito')}${btn('snapshot','Guardar punto de versión','primary')}</div><h1>Versiones de ${esc(c.title)}</h1><p class="muted">Recuperar conserva también una copia del estado actual.</p>${c.versions.length?c.versions.slice().reverse().map(v=>`<div class="version"><div><b>${esc(v.label)}</b><br><small>${esc(new Date(v.date).toLocaleString('es-MX'))}</small></div><button data-restore="${v.id}">Recuperar</button></div>`).join(''):'<div class="panel">Todavía no hay puntos guardados.</div>'}`;bind('back',render);bind('snapshot',()=>{const label=prompt('Nombre de esta versión','Avance de hoy');if(label===null)return;snapshot(c,label||'Versión manual');save();versionsView();});document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{restore(c,b.dataset.restore);sid=c.scenes[0].id;save();versionsView();notify('Versión recuperada; el estado anterior quedó conservado.');});}
function boardView(){$('#main').innerHTML=`<div class="toolbar"><div><div class="eyebrow">ESTRUCTURA NARRATIVA</div><h1>Una historia, pieza por pieza.</h1></div><span class="spacer"></span>${btn('order','Orden del libro',free?'':'primary')}${btn('free','Lienzo libre',free?'primary':'')}</div><p class="muted">${free?'Arrastra los iconos sin cambiar el orden del libro. Selecciona y presiona Enter para abrir.':'Un icono por capítulo. Las flechas cambian el orden del manuscrito; Enter o doble clic abre el documento.'}</p><div id="board"></div>`;bind('order',()=>{free=false;boardView();});bind('free',()=>{free=true;boardView();});const live=p.chapters.filter(c=>!c.trashed);const chapterCard=(c,i)=>`<button class="chapter-icon" data-open="${c.id}" ${free?`style="left:${c.x}px;top:${c.y}px"`:''}>${icon('book','chapter-glyph')}<b>${String(i+1).padStart(2,'0')} · ${esc(c.title)}</b><small>ACTO ${c.act}</small></button>`;$('#board').innerHTML=free?`<div class="canvas"><div class="canvas-inner">${live.map(chapterCard).join('')}</div></div>`:`<div class="grid">${live.map((c,i)=>`<div class="chapter-wrap">${chapterCard(c,i)}<div class="toolbar"><button data-move="${c.id}" data-dir="-1" aria-label="Subir capítulo" ${i===0?'disabled':''}>↑</button><button data-move="${c.id}" data-dir="1" aria-label="Bajar capítulo" ${i===live.length-1?'disabled':''}>↓</button><select data-act="${c.id}" aria-label="Acto de ${esc(c.title)}">${[1,2,3].map(n=>`<option ${c.act===n?'selected':''}>${n}</option>`).join('')}</select></div></div>`).join('')}</div>`;document.querySelectorAll('[data-open]').forEach(b=>{const c=p.chapters.find(c=>c.id===b.dataset.open);const open=()=>{view='write';select(c);};b.ondblclick=open;b.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();open();}};if(free){b.onpointerdown=e=>{const x=e.clientX,y=e.clientY,bx=c.x,by=c.y;b.setPointerCapture(e.pointerId);b.onpointermove=e=>{c.x=Math.max(0,Math.min(1450,bx+e.clientX-x));c.y=Math.max(0,Math.min(850,by+e.clientY-y));b.style.left=c.x+'px';b.style.top=c.y+'px';};b.onpointerup=()=>{b.onpointermove=null;save();};};}});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=p.chapters.findIndex(c=>c.id===b.dataset.move),j=live.findIndex(c=>c.id===b.dataset.move)+Number(b.dataset.dir);const target=p.chapters.indexOf(live[j]);[p.chapters[i],p.chapters[target]]=[p.chapters[target],p.chapters[i]];save();render();});document.querySelectorAll('[data-act]').forEach(s=>s.onchange=()=>{p.chapters.find(c=>c.id===s.dataset.act).act=Number(s.value);save();});}
function archiveView(){$('#main').innerHTML=`<div class="toolbar"><div><div class="eyebrow">ARCHIVO NARRATIVO</div><h1>Todo lo que habita tu historia.</h1></div><span class="spacer"></span><select id="entityType" class="field"><option>Personaje</option><option>Lugar</option><option>Objeto</option><option>Nota</option></select>${btn('addEntity','＋ Nueva ficha','primary')}</div><div class="grid">${p.entities.filter(e=>!e.trashed).map(e=>`<section class="panel entry" data-entity="${e.id}"><span class="eyebrow">${esc(e.type)}</span><label>Nombre<input class="field" data-name value="${esc(e.name)}"></label><label>Descripción y notas<textarea class="field" data-notes>${esc(e.notes)}</textarea></label><button data-trash>A papelera</button></section>`).join('')||'<div class="panel">Crea tu primera ficha. Puedes empezar solo con un nombre.</div>'}</div><details><summary>Fichas en papelera</summary>${p.entities.filter(e=>e.trashed).map(e=>`<button data-recover-entity="${e.id}">↶ ${esc(e.name)}</button>`).join('')}</details>`;bind('addEntity',()=>{p.entities.push({id:uid(),type:$('#entityType').value,name:'Nueva ficha',notes:'',trashed:false});save();archiveView();});document.querySelectorAll('[data-entity]').forEach(el=>{const e=p.entities.find(e=>e.id===el.dataset.entity);el.querySelector('[data-name]').oninput=x=>{e.name=x.target.value;save();};el.querySelector('[data-notes]').oninput=x=>{e.notes=x.target.value;save();};el.querySelector('[data-trash]').onclick=()=>{e.trashed=true;save();archiveView();};});document.querySelectorAll('[data-recover-entity]').forEach(b=>b.onclick=()=>{p.entities.find(e=>e.id===b.dataset.recoverEntity).trashed=false;save();archiveView();});}
function timelineView(){$('#main').innerHTML=`<div class="toolbar"><div><div class="eyebrow">CRONOLOGÍA</div><h1>Lo que ocurrió. Cuándo se cuenta.</h1></div><span class="spacer"></span>${btn('addEvent','＋ Acontecimiento','primary')}</div><p class="muted">Ordena acontecimientos con las flechas. La fecha es libre: “Tres días antes” también sirve. No reordena capítulos.</p>${p.events.filter(e=>!e.trashed).map((e,i)=>`<section class="panel entry" data-event="${e.id}"><div class="toolbar"><span class="eyebrow">${i+1}</span><button data-up aria-label="Subir acontecimiento" ${i===0?'disabled':''}>↑</button><button data-down aria-label="Bajar acontecimiento" ${i===p.events.filter(e=>!e.trashed).length-1?'disabled':''}>↓</button></div><label>Acontecimiento<input class="field" data-title value="${esc(e.title)}"></label><label>Cuándo ocurre<input class="field" data-when value="${esc(e.when)}"></label><label>Se cuenta en<select class="field" data-chapter><option value="">Sin vincular</option>${p.chapters.filter(c=>!c.trashed||c.id===e.chapterId).map(c=>`<option value="${c.id}" ${c.id===e.chapterId?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><button data-trash>A papelera</button></section>`).join('')||'<div class="panel">Todavía no hay acontecimientos.</div>'}<details><summary>Acontecimientos en papelera</summary>${p.events.filter(e=>e.trashed).map(e=>`<button data-recover-event="${e.id}">↶ ${esc(e.title)}</button>`).join('')}</details>`;bind('addEvent',()=>{p.events.push({id:uid(),title:'Nuevo acontecimiento',when:'',chapterId:'',trashed:false});save();timelineView();});document.querySelectorAll('[data-event]').forEach(el=>{const e=p.events.find(e=>e.id===el.dataset.event);for(const [sel,key] of [['title','title'],['when','when'],['chapter','chapterId']])el.querySelector('[data-'+sel+']').oninput=x=>{e[key]=x.target.value;save();};el.querySelector('[data-trash]').onclick=()=>{e.trashed=true;save();timelineView();};for(const [sel,dir] of [['up',-1],['down',1]])el.querySelector('[data-'+sel+']').onclick=()=>{const live=p.events.filter(x=>!x.trashed),target=live[live.indexOf(e)+dir];if(!target)return;const i=p.events.indexOf(e),j=p.events.indexOf(target);[p.events[i],p.events[j]]=[p.events[j],p.events[i]];save();timelineView();};});document.querySelectorAll('[data-recover-event]').forEach(b=>b.onclick=()=>{p.events.find(e=>e.id===b.dataset.recoverEvent).trashed=false;save();timelineView();});}
function reviewView(){let r=p.reviews.find(r=>r.id===reviewId)||p.reviews.at(-1);if(!r){$('#main').innerHTML='<h1>Tu mesa de revisión.</h1><div class="notice">Abre una escena en Escribir y elige Revisar escena. Puedes pegar una propuesta manualmente. La conexión con IA y Drive está pendiente.</div>';return;}reviewId=r.id;const c=p.chapters.find(c=>c.id===r.chapterId),s=c.scenes.find(s=>s.id===r.sceneId);$('#main').innerHTML=`<div class="eyebrow">REVISIÓN MANUAL · SIN CONEXIÓN IA</div><h1>Dos miradas sobre la misma escena.</h1><div class="toolbar"><select id="reviewSelect" class="field" aria-label="Revisión">${p.reviews.map((x,i)=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>Revisión ${i+1}</option>`).join('')}</select><span>${esc(c.title)} / ${esc(s?.title||'Escena de otra versión')}</span></div><label>Instrucción de revisión<input id="instruction" class="field" value="${esc(r.instruction)}" placeholder="Corrige puntuación y conserva mi voz"></label><div class="tabs">${btn('originalTab','Original')}${btn('proposalTab','Propuesta')}</div><div class="split"><section class="panel ${tab!=='original'?'mobile-hidden':''}"><h2>Original enviado</h2><textarea class="field" readonly aria-label="Original enviado">${esc(r.base)}</textarea></section><section class="panel ${tab!=='proposal'?'mobile-hidden':''}"><h2>Propuesta editable</h2><textarea id="proposal" class="field" aria-label="Propuesta de revisión">${esc(r.proposal)}</textarea></section></div><div class="toolbar">${btn('apply','Aplicar propuesta completa','primary')}${btn('request','Descargar solicitud JSON')}</div><p class="muted">V0.1: comparación manual de escena completa; aceptación por cambio y resaltado de diferencias quedan para otra entrega. Aplicar crea una versión previa.</p>`;$('#reviewSelect').onchange=e=>{reviewId=e.target.value;reviewView();};$('#instruction').oninput=e=>{r.instruction=e.target.value;save();};$('#proposal').oninput=e=>{r.proposal=e.target.value;save();};bind('originalTab',()=>{tab='original';reviewView();});bind('proposalTab',()=>{tab='proposal';reviewView();});bind('apply',()=>{if(!s){notify('La escena ya no existe en esta versión.');return;}try{if(s.text!==r.base)throw Error('El original cambió. Inicia otra revisión para evitar sobrescribirlo.');snapshot(c,'Antes de aplicar propuesta');applyReview(s,r);save();notify('Propuesta aplicada. La versión anterior quedó guardada.');}catch(e){notify(e.message);}});bind('request',()=>download('MORIARTY_SOLICITUD.json',JSON.stringify({schemaVersion:1,kind:'review-request',...r},null,2)));}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.body.classList.remove('focus');render();});
$('#projectTitle').oninput=e=>{p.title=e.target.value;save();};
bind('export',()=>view==='library'?backupLibrary():download('MORIARTY_LIBRO.moriarty.json',JSON.stringify(p,null,2)));
bind('txt',()=>download('MORIARTY_MANUSCRITO.txt',p.title+'\n\n'+p.chapters.filter(c=>!c.trashed).map(c=>c.title+'\n\n'+c.scenes.map(s=>s.title+'\n\n'+s.text).join('\n\n')).join('\n\n────────\n\n'),'text/plain;charset=utf-8'));
bind('import',()=>$('#file').click());
$('#file').onchange=async e=>{
 const f=e.target.files[0];if(!f)return;
 try{
  if(f.size>25*1024*1024)throw Error('El archivo supera 25 MB.');
  const data=JSON.parse(await f.text());
  const next=loadFailure?(data?.kind==='moriarty-library'?validateLibrary(data):createLibrary(validate(data))):importIntoLibrary(library,data);
  if(loadFailure){if(!confirm('El guardado actual es ilegible. Se descargará una copia de recuperación antes de abrir este respaldo. ¿Continuar?'))return;downloadRecovery();}
  library=next;loadFailure=false;openBook(library.activeBookId);notify('Importado. Tus otros libros se conservan en la biblioteca.');
 }catch(err){notify(err.message);}finally{e.target.value='';}
};
bind('new',()=>{if(loadFailure){notify('Recupera un respaldo antes de crear libros. El guardado ilegible se conserva.');return;}libraryView.bookDialog();});
bind('downloadRecovery',downloadRecovery);
bind('resetLibrary',()=>{if(!confirm('Se descargará el guardado ilegible para recuperarlo antes de iniciar una biblioteca nueva. ¿Continuar?'))return;downloadRecovery();library=createLibrary();p=activeBook(library).project;loadFailure=false;cid=p.chapters[0].id;sid=current().scenes[0].id;view='library';save();render();});
render();
if(loadFailure){$('#saved').textContent='⚠ No se pudo leer la biblioteca · Guardado bloqueado';}else{save();if(migrated)notify('Tu libro de V0.1 ya está en la biblioteca. Conservamos el guardado original.');}
const iconObserver=new MutationObserver(()=>decorateIcons());iconObserver.observe(document.body,{childList:true,subtree:true});
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>notify('Modo sin conexión no disponible en este navegador.'));
